/**
 * EmberTrace – data for the story page, read from /story.json.
 * That file is generated by scripts/build_story_data.py from data/cell_month.parquet;
 * no number on the story page is typed in by hand.
 */

import { useEffect, useState } from 'react';

export type Source = 'TERRA_chained' | 'AQUA_calibrated' | 'VIIRS';

export interface StoryYear {
  year: number;
  months: number; // months of data in this year (12 = full year)
  naive_raw: number; // raw detections of the month's source sensor, stitched end to end
  viirs_raw: number; // raw VIIRS detections, all VIIRS satellites together
  harmonized: number; // EmberTrace VIIRS-equivalent detections per satellite (pipeline output)
  aqua_converted: number | null; // Aqua converted with the pipeline's calibration, in VIIRS years only (the check)
  sources: Source[];
}

export interface StoryData {
  data_kind: 'real' | 'synthetic';
  pipeline_version: string;
  coverage: { first_month: string; last_month: string };
  cell_size_deg: number;
  conversion: {
    method: string; // calibration method in data/calibration.json, e.g. "monthly_ratio"
    aqua_to_viirs_range: [number, number]; // smallest and largest factor (equal for a single factor)
    terra_to_aqua_range: [number, number];
    aqua_to_viirs_window: [string, string];
    terra_to_aqua_window: [string, string];
  };
  satellites: Record<string, { series: string; start: string }>;
  years: StoryYear[];
  cells_years: [number, number];
  cells: [number, number, number][]; // [lat, lon, mean yearly detections]
  /** Worldwide context layer: FIRMS global 7-day file, not harmonized. Absent if not downloaded. */
  world?: {
    satellites: string[];
    dates: [string, string];
    detections: number;
    cell_size_deg: number;
    cells: [number, number, number][]; // [lat, lon, detections in the 7 days]
  };
}

export function useStoryData() {
  const [data, setData] = useState<StoryData | null>(null);
  const [error, setError] = useState(false);
  useEffect(() => {
    fetch(`${import.meta.env.BASE_URL}story.json`)
      .then((r) => (r.ok ? r.json() : Promise.reject(r.status)))
      .then(setData)
      .catch(() => setError(true));
  }, []);
  return { data, error };
}

/** 447660 -> "448k", 1362781 -> "1.36M" */
export function formatCount(n: number): string {
  if (n >= 1e6) return `${(n / 1e6).toFixed(2)}M`;
  if (n >= 1e4) return `${Math.round(n / 1e3)}k`;
  if (n >= 1e3) return `${(n / 1e3).toFixed(1)}k`;
  return String(Math.round(n));
}

/** "7.43–16.67" for a range of factors, "7.98" when there is only one. */
export function factorRange([lo, hi]: [number, number]): string {
  return lo === hi ? lo.toFixed(2) : `${lo.toFixed(2)}–${hi.toFixed(2)}`;
}

export function yearOf(isoDate: string): number {
  return Number(isoDate.slice(0, 4));
}

/** Same epoch colours as the explorer calendar (features/charts/AGENTS.md). */
export const SOURCE_COLOR: Record<Source, string> = {
  TERRA_chained: '#c084fc',
  AQUA_calibrated: '#60a5fa',
  VIIRS: '#34d399',
};

export const SOURCE_LABEL: Record<Source, string> = {
  TERRA_chained: 'Terra (MODIS)',
  AQUA_calibrated: 'Aqua (MODIS)',
  VIIRS: 'VIIRS',
};
